const PAGE_CSS: string = ".price-btn { \n        /* allow buttons to shrink on small screens and expand on larger */\n        min-width: 0; \n        flex: 1 1 auto;\n        font-size: 0.9rem;\n        white-space: normal;\n    }\n    @media (max-width: 767.98px) {\n        /* two buttons per row on small viewports */\n        .price-btn { flex: 0 0 48%; }\n    }\n    .price-btn small {\n        font-size: 0.75rem;\n        display: block;\n    }\n    .card-header { font-weight: 600; }\n    #groupCodeSmall {\n        font-size: 1.05rem;\n        padding: 0.35rem 0.6rem;\n        font-weight: 700;\n    }\n    #seatsContainer {\n        display: inline-flex;\n        align-items: center;\n        background-color: #198754;\n        color: #fff;\n        border-radius: 999px;\n        overflow: hidden;\n        font-weight: 600;\n    }\n    #seatsContainer #seatsLabel {\n        padding: 0.35rem 0.6rem;\n        color: #fff;\n        margin: 0;\n        line-height: 1;\n        border-right: 1px solid rgba(255, 255, 255, 0.35);\n    }\n    #seatsContainer #availableSeats {\n        background: transparent;\n        color: #fff;\n        padding: 0.35rem 0.6rem;\n        font-size: 1.15rem;\n        margin: 0;\n        line-height: 1;\n    }\n    /* Success result styling: match screenshot light mint green panel and green text */\n    .registration-success-card .card {\n        background-color: #d9f0e0 !important; /* screenshot-like mint green */\n        border: 1px solid #0f5132 !important; /* dark green border */\n        border-radius: 6px;\n        box-shadow: none;\n    }\n    .registration-success-card .card-body {\n        background-color: transparent !important;\n        padding: 1rem 1.25rem !important;\n    }\n    .registration-success-card h3,\n    .registration-success-card p,\n    .registration-success-card strong,\n    .registration-success-card .mb-1 {\n        color: #0f5132 !important; /* dark green text */\n    }\n    /* Make the entire message area use the same green (including paragraphs and bold text) */\n    .registration-success-card .text-start p { margin-bottom: 0.25rem; }\n    /* Passenger card header: always visible to clearly identify card boundaries */\n    .passenger-card-header {\n        background-color: #b7c2ff !important;\n        padding: 0.5rem 0.75rem;\n        border-bottom: 1px solid rgba(0,0,0,0.06);\n        border-top-left-radius: 0.5rem !important;\n        border-top-right-radius: 0.5rem !important;\n        font-weight: 600;\n    }\n    /* Mobile passenger card separators */\n    @media (max-width: 767.98px) {\n        #passengersCards .col-12 { padding-left: 0; padding-right: 0; }\n        #passengersCards .card {\n            border: 1px solid rgba(0,0,0,0.18); /* darker separator */\n            box-shadow: none;\n            border-radius: 0.5rem;\n        }\n        /* Add a clear separator between stacked cards */\n        #passengersCards .col-12:not(:last-child) { margin-bottom: 0.75rem; }\n    }\n\n/* --------------------------------------------------------------------------\n   Green, gold and cream Umrah theme inspired by the supplied poster\n   -------------------------------------------------------------------------- */\n:root {\n    --umrah-green-950: #022d22;\n    --umrah-green-900: #063d2d;\n    --umrah-green-800: #07513a;\n    --umrah-green-700: #0b6848;\n    --umrah-gold-800: #95670c;\n    --umrah-gold-700: #b98518;\n    --umrah-gold-600: #cfa43c;\n    --umrah-gold-500: #e0bd65;\n    --umrah-gold-300: #f1dc9c;\n    --umrah-cream-50: #fffdf8;\n    --umrah-cream-100: #fff8e9;\n    --umrah-cream-200: #f9ecd0;\n    --umrah-cream-300: #f0ddb2;\n    --umrah-red-700: #9f1717;\n    --umrah-ink: #183126;\n    --umrah-muted: #66736c;\n    --umrah-border: rgba(185, 133, 24, .35);\n    --umrah-shadow: 0 16px 38px rgba(2, 45, 34, .12);\n}\n\nhtml,\nbody {\n    min-height: 100%;\n    background:\n        radial-gradient(circle at 8% 2%, rgba(224, 189, 101, .20), transparent 28rem),\n        radial-gradient(circle at 94% 8%, rgba(7, 81, 58, .11), transparent 30rem),\n        linear-gradient(180deg, var(--umrah-cream-50), var(--umrah-cream-100));\n}\n\nbody {\n    color: var(--umrah-ink);\n}\n\n.content-body {\n    min-height: 100vh;\n    padding-bottom: 2rem;\n    color: var(--umrah-ink);\n    background:\n        linear-gradient(30deg, transparent 24%, rgba(224, 189, 101, .055) 25%, rgba(224, 189, 101, .055) 27%, transparent 28%, transparent 74%, rgba(224, 189, 101, .055) 75%, rgba(224, 189, 101, .055) 77%, transparent 78%) 0 0 / 44px 76px,\n        linear-gradient(150deg, transparent 24%, rgba(224, 189, 101, .045) 25%, rgba(224, 189, 101, .045) 27%, transparent 28%, transparent 74%, rgba(224, 189, 101, .045) 75%, rgba(224, 189, 101, .045) 77%, transparent 78%) 0 0 / 44px 76px;\n}\n\n.content-body .page-header {\n    position: relative;\n    min-height: 92px;\n    margin: 0;\n    overflow: hidden;\n    border: 0;\n    border-bottom: 4px solid var(--umrah-gold-600);\n    background:\n        radial-gradient(circle at 82% -80%, rgba(255,255,255,.16), transparent 18rem),\n        linear-gradient(120deg, var(--umrah-green-950), var(--umrah-green-800) 64%, var(--umrah-green-700));\n    box-shadow: 0 12px 30px rgba(2,45,34,.20);\n}\n\n.content-body .page-header::before {\n    content: \"LABBAIK ALLAHUMMA LABBAIK\";\n    position: absolute;\n    left: clamp(1rem, 5vw, 4rem);\n    top: 50%;\n    transform: translateY(-50%);\n    color: var(--umrah-gold-300);\n    font-family: Georgia, \"Times New Roman\", serif;\n    font-size: clamp(.88rem, 2vw, 1.2rem);\n    font-weight: 700;\n    letter-spacing: .18em;\n}\n\n.content-body .page-header::after {\n    content: \"\u2726\";\n    position: absolute;\n    right: clamp(1rem, 5vw, 4rem);\n    top: 50%;\n    transform: translateY(-50%);\n    color: var(--umrah-gold-500);\n    font-size: 2rem;\n}\n\n.content-body > .container,\n.content-body .container.mt-4 {\n    max-width: 1320px;\n}\n\n.content-body .card {\n    overflow: hidden;\n    border: 1px solid var(--umrah-border);\n    border-radius: 18px;\n    background: rgba(255,255,255,.94);\n    box-shadow: var(--umrah-shadow);\n}\n\n.content-body .card-header {\n    padding: .9rem 1.15rem;\n    color: var(--umrah-cream-50);\n    background:\n        linear-gradient(135deg, var(--umrah-green-950), var(--umrah-green-800));\n    border-bottom: 3px solid var(--umrah-gold-600);\n    font-weight: 800;\n    letter-spacing: .015em;\n}\n\n.content-body .card-body {\n    background:\n        linear-gradient(180deg, rgba(255,255,255,.98), rgba(255,250,240,.84));\n}\n\n.content-body .col-form-label,\n.content-body .form-label,\n.content-body strong {\n    color: var(--umrah-green-950);\n}\n\n.content-body .form-control,\n.content-body .form-select {\n    color: var(--umrah-ink);\n    border: 1px solid rgba(185,133,24,.38);\n    border-radius: 11px;\n    background-color: rgba(255,255,255,.95);\n}\n\n.content-body .form-control:hover,\n.content-body .form-select:hover {\n    border-color: var(--umrah-gold-600);\n}\n\n.content-body .form-control:focus,\n.content-body .form-select:focus {\n    border-color: var(--umrah-gold-600);\n    box-shadow: 0 0 0 .22rem rgba(224,189,101,.23);\n}\n\n.content-body .input-group .btn {\n    border-color: rgba(185,133,24,.42);\n}\n\n.content-body .btn-primary {\n    --bs-btn-color: #fff;\n    --bs-btn-bg: var(--umrah-green-800);\n    --bs-btn-border-color: var(--umrah-green-800);\n    --bs-btn-hover-color: var(--umrah-green-950);\n    --bs-btn-hover-bg: var(--umrah-gold-500);\n    --bs-btn-hover-border-color: var(--umrah-gold-500);\n    --bs-btn-active-color: var(--umrah-green-950);\n    --bs-btn-active-bg: var(--umrah-gold-600);\n    --bs-btn-active-border-color: var(--umrah-gold-600);\n    border-radius: 11px;\n    font-weight: 800;\n    box-shadow: 0 7px 17px rgba(2,45,34,.16);\n}\n\n.content-body .btn-outline-secondary {\n    --bs-btn-color: var(--umrah-green-800);\n    --bs-btn-border-color: rgba(7,81,58,.42);\n    --bs-btn-hover-color: #fff;\n    --bs-btn-hover-bg: var(--umrah-green-800);\n    --bs-btn-hover-border-color: var(--umrah-green-800);\n    --bs-btn-active-color: var(--umrah-green-950);\n    --bs-btn-active-bg: var(--umrah-gold-500);\n    --bs-btn-active-border-color: var(--umrah-gold-500);\n    border-radius: 11px;\n    font-weight: 700;\n}\n\n.content-body .price-btn {\n    min-height: 72px;\n    color: var(--umrah-green-950);\n    border: 1px solid rgba(185,133,24,.42);\n    border-radius: 13px;\n    background:\n        linear-gradient(145deg, #fffdf8, var(--umrah-cream-200));\n    box-shadow: 0 7px 16px rgba(2,45,34,.08);\n    font-weight: 800;\n    transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease;\n}\n\n.content-body .price-btn:hover,\n.content-body .price-btn:focus {\n    color: var(--umrah-green-950);\n    border-color: var(--umrah-gold-700);\n    background: linear-gradient(145deg, var(--umrah-gold-300), #fff8dc);\n    transform: translateY(-2px);\n    box-shadow: 0 12px 24px rgba(2,45,34,.13);\n}\n\n.content-body .price-btn small {\n    color: var(--umrah-red-700);\n    font-size: .82rem;\n    font-weight: 900;\n}\n\n.content-body #groupTitle {\n    color: var(--umrah-green-950);\n    font-family: Georgia, \"Times New Roman\", serif;\n    font-weight: 800;\n}\n\n.content-body #groupCodeSmall,\n.content-body .badge.bg-success,\n.content-body #seatsContainer {\n    color: #fff !important;\n    background: var(--umrah-green-700) !important;\n    border: 1px solid rgba(241,220,156,.42);\n}\n\n.content-body #groupCodeBadge,\n.content-body .badge.bg-warning {\n    color: var(--umrah-green-950) !important;\n    background:\n        linear-gradient(135deg, var(--umrah-gold-300), var(--umrah-gold-600)) !important;\n    border: 1px solid var(--umrah-gold-700);\n}\n\n.content-body #groupDates,\n.content-body .text-muted {\n    color: var(--umrah-muted) !important;\n}\n\n.content-body hr {\n    border-color: rgba(185,133,24,.35);\n    opacity: 1;\n}\n\n.content-body .passenger-card-header {\n    color: var(--umrah-cream-50) !important;\n    background:\n        linear-gradient(135deg, var(--umrah-green-900), var(--umrah-green-700)) !important;\n    border-bottom: 3px solid var(--umrah-gold-600);\n}\n\n.content-body #passengersTable {\n    overflow: hidden;\n    border-radius: 12px;\n}\n\n.content-body #passengersTable thead th {\n    color: #fff;\n    background: var(--umrah-green-900);\n    border-color: rgba(241,220,156,.32);\n    white-space: nowrap;\n}\n\n.content-body #passengersTable tbody td {\n    border-color: rgba(185,133,24,.22);\n    background: rgba(255,255,255,.92);\n}\n\n.content-body #passengersTable tbody tr:nth-child(even) td {\n    background: rgba(255,248,233,.78);\n}\n\n.content-body #customerSuggestions {\n    overflow: hidden;\n    border: 1px solid var(--umrah-border);\n    border-radius: 12px;\n    box-shadow: 0 15px 30px rgba(2,45,34,.17);\n}\n\n.content-body #customerSuggestions .list-group-item {\n    border-color: rgba(185,133,24,.18);\n}\n\n.content-body #customerSuggestions .list-group-item:hover,\n.content-body #customerSuggestions .list-group-item.active {\n    color: #fff;\n    background: var(--umrah-green-700);\n    border-color: var(--umrah-green-700);\n}\n\n.content-body .form-check-input:checked {\n    background-color: var(--umrah-green-700);\n    border-color: var(--umrah-green-700);\n}\n\n.content-body .form-check-input:focus {\n    border-color: var(--umrah-gold-600);\n    box-shadow: 0 0 0 .2rem rgba(224,189,101,.22);\n}\n\n.content-body .alert-info,\n.content-body .alert-warning {\n    color: var(--umrah-green-950);\n    background: var(--umrah-cream-200);\n    border-color: var(--umrah-gold-600);\n}\n\n.content-body .alert-danger {\n    color: #741414;\n    background: #fff0ed;\n    border-color: #d98b7f;\n}\n\n.content-body .registration-success-card .card {\n    background:\n        linear-gradient(145deg, #e8f5e9, #f5ffef) !important;\n    border: 1px solid var(--umrah-green-700) !important;\n    box-shadow: var(--umrah-shadow);\n}\n\n.content-body .registration-success-card h3,\n.content-body .registration-success-card p,\n.content-body .registration-success-card strong {\n    color: var(--umrah-green-900) !important;\n}\n\n.content-body #registerBtn {\n    min-width: 128px;\n}\n\n.content-body a.btn {\n    text-decoration: none;\n}\n\n.content-body * {\n    scrollbar-width: thin;\n    scrollbar-color: var(--umrah-gold-600) rgba(249,236,208,.72);\n}\n\n.content-body *::-webkit-scrollbar {\n    width: 9px;\n    height: 9px;\n}\n\n.content-body *::-webkit-scrollbar-track {\n    background: rgba(249,236,208,.72);\n}\n\n.content-body *::-webkit-scrollbar-thumb {\n    border: 2px solid var(--umrah-cream-100);\n    border-radius: 999px;\n    background: var(--umrah-gold-600);\n}\n\n@media (max-width: 767.98px) {\n    .content-body .page-header {\n        min-height: 76px;\n    }\n\n    .content-body .page-header::before {\n        max-width: calc(100% - 5rem);\n        font-size: .76rem;\n        letter-spacing: .1em;\n    }\n\n    .content-body .container.mt-4 {\n        margin-top: 1rem !important;\n        padding-inline: .75rem;\n    }\n\n    .content-body .card {\n        border-radius: 14px;\n    }\n\n    .content-body .price-btn {\n        flex: 0 0 calc(50% - .5rem);\n    }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .content-body *,\n    .content-body *::before,\n    .content-body *::after {\n        scroll-behavior: auto !important;\n        transition: none !important;\n    }\n}";

const PAGE_SCRIPT: string = "(function () {\n        // Current user information from server\n        const currentUser = {\n            oid: 'a34a5359-9e59-4c97-ae0f-4660534aa55d',\n            isCustomer: false,\n            fullName: 'System Administrator'\n        };\n            // passenger validation enabled flag comes from server-side ViewBag.PassengerValidationEnabled (default true)\n            const passengerValidationEnabled = true;\n\n        const msgDiv = document.getElementById('message');\n        function setMessage(text, type) {\n            // Clear any existing message content\n            msgDiv.innerHTML = '';\n\n            const alertType = type || 'info';\n            const wrapper = document.createElement('div');\n            wrapper.className = 'alert alert-' + alertType;\n            wrapper.setAttribute('role', 'alert');\n            wrapper.innerHTML = String(text || '');\n\n            // If the error mentions available seats, show a \"Try Other Group\" button\n            try {\n                if (String(text || '').toLowerCase().indexOf('sorry. all seats are reserved. please select some other package.') !== -1) {\n                    // When this specific error occurs, hide Reservation Details, Group Details and Passengers\n                    try {\n                        function hideEl(el){ if(!el) return; try{ el.style.display='none'; el.classList.add('d-none'); el.setAttribute('aria-hidden','true'); }catch(e){} }\n\n                        // Hide reservation area by id, card header text or nearest column\n                        const resForm = document.getElementById('reservationForm');\n                        if (resForm) hideEl(resForm.closest('.col-md-6') || resForm.closest('.card') || resForm);\n\n                        // Hide group details by known id or header text\n                        const groupTitle = document.getElementById('groupTitle');\n                        if (groupTitle) hideEl(groupTitle.closest('.col-md-6') || groupTitle.closest('.card') || groupTitle);\n\n                        // Fallback: hide any card whose header mentions Reservation Details or Group Details\n                        document.querySelectorAll('.card-header').forEach(ch => {\n                            try {\n                                const txt = (ch.textContent || '').trim().toLowerCase();\n                                if (txt.indexOf('reservation details') !== -1 || txt.indexOf('group details') !== -1) {\n                                    const container = ch.closest('.col-md-6') || ch.closest('.card') || ch;\n                                    hideEl(container);\n                                }\n                            } catch (inner) { }\n                        });\n\n                        // Hide Passengers section (card that contains #passengersResponsive)\n                        const passResp = document.getElementById('passengersResponsive');\n                        if (passResp) hideEl(passResp.closest('.card') || passResp);\n\n                        // Hide footer action card (register/cancel)\n                        hideEl(document.querySelector('div.card.p-3.mb-5'));\n\n                        // Ensure message is visible at top\n                        try { window.scrollTo({ top: 0, behavior: 'smooth' }); } catch (s) { window.scrollTo(0, 0); }\n                    } catch (hideEx) { console.warn('Failed to hide sections for seat error', hideEx); }\n                    const btn = document.createElement('button');\n                    btn.type = 'button';\n                    btn.id = 'tryOtherGroupBtn';\n                    btn.className = 'btn btn-outline-primary btn-sm ms-2';\n                    btn.textContent = 'Try Other Group';\n                    btn.addEventListener('click', function () {\n                        try {\n                            // Attempt to hide all likely form containers/sections so fields are not visible\n                            const selectors = [\n                                'div.container.mt-4', // main wrapper\n                                'form#reservationForm',\n                                '#passengersResponsive',\n                                '#passengersCards',\n                                '#passengersTable',\n                                'div.card.p-3.mb-5' // footer action card\n                            ];\n                            selectors.forEach(s => {\n                                try {\n                                    const el = document.querySelector(s);\n                                    if (el) el.style.display = 'none';\n                                } catch (ignore) { }\n                            });\n\n                            // Also add a visual overlay to obscure the page briefly\n                            const overlay = document.createElement('div');\n                            overlay.id = 'tryOtherGroupOverlay';\n                            overlay.style.position = 'fixed';\n                            overlay.style.top = '0';\n                            overlay.style.left = '0';\n                            overlay.style.width = '100%';\n                            overlay.style.height = '100%';\n                            overlay.style.background = 'rgba(255,255,255,0.8)';\n                            overlay.style.zIndex = '9999';\n                            document.body.appendChild(overlay);\n\n                            // Delay navigation slightly to ensure hide takes effect for the user\n                            setTimeout(function () {\n                                try { window.location.href = '/UMR/UmrahGroups'; } catch (e) { /* ignore */ }\n                            }, 200);\n                        } catch (ex) { console.warn('Try Other Group click failed', ex); try { window.location.href = '/UMR/UmrahGroups'; } catch (_) { } }\n                    });\n                    // Append a small wrapper so button shows next to message\n                    const btnWrap = document.createElement('span');\n                    btnWrap.className = 'd-inline-block align-middle ms-2';\n                    btnWrap.appendChild(btn);\n                    wrapper.appendChild(btnWrap);\n                }\n            } catch (ex) { console.warn('setMessage helper failed to evaluate special actions', ex); }\n\n            msgDiv.appendChild(wrapper);\n        }\n\n        // Show a success UI after saving reservation: hide form and display message with action buttons\n        function showReservationSuccessUI(resObj, resNo) {\n            try {\n                // Find main container form\n                const mainContainer = document.querySelector('div.container.mt-4');\n\n                // Determine reservation number and oid\n                // Prefer the local saved reservation number (from resObj) when available;\n                // fall back to the external/resNo when local value is not present.\n                const reservationNumber = (resObj && (resObj.ReservationNo || resObj.reservationNo || (resObj.value && resObj.value.ReservationNo))) || resNo || '';\n                const oid = (function (r) {\n                    if (!r) return '';\n                    if (r.Oid) return r.Oid;\n                    if (r.oid) return r.oid;\n                    if (r.Id) return r.Id;\n                    if (r.id) return r.id;\n                    if (r.value) {\n                        if (r.value.Oid) return r.value.Oid;\n                        if (r.value.oid) return r.value.oid;\n                        if (Array.isArray(r.value) && r.value.length > 0) {\n                            const v0 = r.value[0];\n                            if (v0 && (v0.Oid || v0.oid)) return v0.Oid || v0.oid;\n                        }\n                    }\n                    return '';\n                })(resObj) || '';\n\n                // Create result container\n                const resultDiv = document.createElement('div');\n                resultDiv.id = 'registrationResult';\n                resultDiv.className = 'container mt-4 registration-success-card';\n                resultDiv.innerHTML = `\n                    <div class=\"card\">\n                        <div class=\"card-body\">\n                            <div class=\"text-start\">\n                                <h3>Success!</h3>\n                                <p class=\"mb-1\">Reservations saved successfully with No: <strong>${reservationNumber || 'UR-100290'}</strong></p>\n                                <p>Your request for Umrah Group reservation is submitted to Head Office for further process.</p>\n                            </div>\n                            <div class=\"mt-3 text-center\">\n                                <button id=\"printTicketBtn\" class=\"btn btn-primary me-2\" style=\"display:none\">Print Ticket</button>\n                                <button id=\"printInvoiceBtn\" class=\"btn btn-secondary me-2\" style=\"display:none\">Print Invoice</button>\n                                <button id=\"groupListBtn\" class=\"btn btn-outline-secondary\">Back to Group List</button>\n                            </div>\n                        </div>\n                    </div>\n                `;\n\n                // Insert resultDiv before mainContainer so it appears at the top of the page\n                if (mainContainer && mainContainer.parentNode) {\n                    mainContainer.parentNode.insertBefore(resultDiv, mainContainer);\n                    // Hide the main container after inserting the result so user sees message at top\n                    mainContainer.style.display = 'none';\n                } else {\n                    // Fallback: prepend to body\n                    document.body.insertBefore(resultDiv, document.body.firstChild);\n                }\n\n                // Scroll to top so the message is visible without user scrolling\n                try { window.scrollTo({ top: 0, behavior: 'smooth' }); } catch (s) { window.scrollTo(0, 0); }\n\n                // Attach button handlers\n                const printTicketBtn = document.getElementById('printTicketBtn');\n                const printInvoiceBtn = document.getElementById('printInvoiceBtn');\n                const groupListBtn = document.getElementById('groupListBtn');\n\n                if (printTicketBtn) printTicketBtn.addEventListener('click', function () {\n                    if (oid && oid.length > 0) {\n                        window.location.href = '/CRM/UMR/PrintTicket.aspx?Oid=' + encodeURIComponent(oid);\n                    } else {\n                        setMessage('Reservation Oid not available for printing ticket.', 'warning');\n                    }\n                });\n\n                if (printInvoiceBtn) printInvoiceBtn.addEventListener('click', function () {\n                    if (oid && oid.length > 0) {\n                        window.location.href = '/CRM/UMR/PrintInvoice.aspx?Oid=' + encodeURIComponent(oid);\n                    } else {\n                        setMessage('Reservation Oid not available for printing invoice.', 'warning');\n                    }\n                });\n\n                if (groupListBtn) groupListBtn.addEventListener('click', function () {\n                    // Navigate to groups only when user clicks\n                    window.location.href = '/UMR/UmrahGroups';\n                });\n            } catch (ex) {\n                console.error('Failed to display reservation success UI', ex);\n                setMessage('Reservation created successfully.', 'success');\n            }\n        }\n\n        function getQueryParam(name) { const params = new URLSearchParams(window.location.search); return params.get(name); }\n\n        const oid = getQueryParam('oid');\n        if (!oid) { setMessage('No Oid provided in query string.', 'warning'); return; }\n\n        const key = 'selectedUmrGroup_' + oid;\n        const raw = sessionStorage.getItem(key);\n        if (!raw) { setMessage('Selected record not found in session storage. Please go back and select a group.', 'warning'); return; }\n\n        let item = null;\n        try { item = JSON.parse(raw); } catch (ex) { console.error(ex); setMessage('Failed to parse selected record.', 'danger'); return; }\n\n        // Normalize common property casing so code can rely on consistent names\n        try {\n            // Ensure EndPoint is available under item.EndPoint regardless of source casing\n            item.EndPoint = item.EndPoint ?? item.endPoint ?? item.EndPointUrl ?? item.endpoint ?? item.Endpoint ?? '';\n            item.DomainToken = item.DomainToken ?? item.domainToken ?? item.DomainToken ?? item.Token ?? item.token ?? '';\n            item.CustomerOid = item.CustomerOid ?? item.customerOid ?? item.CustomerId ?? item.CustomerId ?? item.CustomerOid ?? '';\n        } catch (ex) { /* ignore normalization errors */ }\n\n        // Populate Group Details\n        document.getElementById('groupTitle').textContent = item.GroupTitle || item.groupTitle || '';\n        document.getElementById('groupCodeBadge').textContent = (item.GroupCode || item.groupCode || '').slice(0, 8);\n        document.getElementById('groupCodeSmall').textContent = item.GroupCode || item.groupCode || item.PackageCode || '';\n        document.getElementById('airline').textContent = item.Airline || item.airline || '';\n        document.getElementById('makkah').textContent = item.MakkahHotel || item.MakkahHotel || '';\n        document.getElementById('medinah').textContent = item.MedinahHotel || item.MedinahHotel || '';\n        document.getElementById('availableSeats').textContent = item.AvailableSeats ?? item.availableSeats ?? '0';\n\n        // Enforce PAX selection limit based on available seats\n        function getAvailableSeatsNumber() {\n            const el = document.getElementById('availableSeats');\n            if (!el) return 0;\n            const v = parseInt(el.textContent || el.innerText || '0', 10);\n            return isNaN(v) ? 0 : v;\n        }\n\n        function applyPaxLimit(showAlert) {\n            const avail = getAvailableSeatsNumber();\n            const select = document.getElementById('paxCount');\n            if (!select) return;\n\n            // Disable options greater than available seats\n            Array.from(select.options).forEach(opt => {\n                const val = parseInt(opt.value || '0', 10);\n                if (isNaN(val)) {\n                    // keep non-numeric (placeholder) enabled\n                    opt.disabled = false;\n                } else {\n                    opt.disabled = (avail === 0) || (val > avail);\n                }\n            });\n\n            // If current selected value exceeds available, adjust it\n            const cur = parseInt(select.value || '0', 10);\n            if (!isNaN(cur) && cur > avail) {\n                const newVal = avail > 0 ? String(avail) : '';\n                select.value = newVal;\n                if (showAlert) setMessage('Selected PAX exceeds available seats. Adjusted to ' + (avail || 0) + '.', 'warning');\n            }\n        }\n\n        // After setting available seats, ensure pax options respect limit\n        applyPaxLimit(false);\n\n        // Format and display travel/booking dates\n        function formatDateSafe(dateValue) {\n            if (!dateValue) return null;\n            try {\n                // Handle Microsoft JSON date format: /Date(timestamp)/\n                let d;\n                if (typeof dateValue === 'string' && dateValue.startsWith('/Date(') && dateValue.endsWith(')/')) {\n                    const timestamp = parseInt(dateValue.substring(6, dateValue.length - 2));\n                    d = new Date(timestamp);\n                } else {\n                    d = new Date(dateValue);\n                }\n\n                if (isNaN(d.getTime())) return null;\n\n                // Format as dd/MM/yyyy\n                const day = String(d.getDate()).padStart(2, '0');\n                const month = String(d.getMonth() + 1).padStart(2, '0');\n                const year = d.getFullYear();\n                return `${day}/${month}/${year}`;\n            } catch {\n                return null;\n            }\n        }\n\n        // Try TravelDate or DepartureDate first, then fall back to BookingStartDate/BookingEndDate\n        const travelDate = item.TravelDate || item.travelDate || item.DepartureDate || item.departureDate;\n        const bStart = item.BookingStartDate || item.bookingStartDate;\n        const bEnd = item.BookingEndDate || item.bookingEndDate;\n\n        let dateText = '';\n        if (travelDate) {\n            const formatted = formatDateSafe(travelDate);\n            if (formatted) {\n                dateText = 'Travel: ' + formatted;\n            }\n        }\n        if (!dateText && (bStart || bEnd)) {\n            const startFormatted = formatDateSafe(bStart);\n            const endFormatted = formatDateSafe(bEnd);\n            if (startFormatted || endFormatted) {\n                dateText = (startFormatted || '') + (endFormatted ? ' - ' + endFormatted : '');\n            }\n        }\n\n        if (dateText) {\n            document.getElementById('groupDates').textContent = dateText;\n        } else {\n            document.getElementById('groupDates').textContent = '-';\n        }\n\n        function fmtCurrency(v, currency) {\n            if (v === null || v === undefined || v === '') return '-';\n            const num = Number(v);\n            if (!isNaN(num)) {\n                try {\n                    return new Intl.NumberFormat(undefined, { style: 'currency', currency: currency || 'PKR' }).format(num);\n                } catch { return (currency || 'PKR') + ' ' + num.toLocaleString(); }\n            }\n            return String(v);\n        }\n\n        // Use DTO property names from UmrGroupViewDto: Sharing, QuadRoom, TripleRoom, DoubleRoom\n        const currencyId = item.CurrencyId || item.currencyId || 'PKR';\n        document.getElementById('priceSharingVal').textContent = fmtCurrency(item.Sharing ?? item.sharing ?? '', currencyId);\n        document.getElementById('priceQuadVal').textContent = fmtCurrency(item.QuadRoom ?? item.quadRoom ?? item.Quad ?? item.quad ?? '', currencyId);\n        document.getElementById('priceTripleVal').textContent = fmtCurrency(item.TripleRoom ?? item.tripleRoom ?? item.Triple ?? item.triple ?? '', currencyId);\n        document.getElementById('priceDoubleVal').textContent = fmtCurrency(item.DoubleRoom ?? item.doubleRoom ?? item.Double ?? item.double ?? '', currencyId);\n\n        // Variable to store the total discount amount\n        let totalDiscountAmount = 0;\n\n        // Fetch and display total discount\n        const packageOid = oid; // Use the package Oid from URL\n        const packageCode = item.PackageCode || item.packageCode || item.GroupCode || item.groupCode || '';\n\n        console.log('Fetching discount for packageOid:', packageOid, 'packageCode:', packageCode);\n\n        if (packageOid) {\n            fetch(`/UMR/GetTotalDiscount/?packageOid=${encodeURIComponent(packageOid)}&packageCode=${encodeURIComponent(packageCode)}`)\n                .then(response => {\n                    console.log('GetTotalDiscount response status:', response.status);\n                    return response.json();\n                })\n                .then(data => {\n                    console.log('GetTotalDiscount data:', data);\n                    if (data.success && data.totalDiscount > 0) {\n                        // Store the discount amount for use when saving reservation\n                        totalDiscountAmount = data.totalDiscount;\n\n                        const discountText = `Discount: ${data.totalDiscount.toFixed(0)} /Per Pax`;\n                        document.getElementById('discountInfo').textContent = discountText;\n                        // In case discount fetch changes availability on remote, re-apply pax limit\n                        applyPaxLimit(false);\n                    } else {\n                        console.log('No discount or error:', data);\n                    }\n                })\n                .catch(err => {\n                    console.error('Error fetching discount:', err);\n                });\n        } else {\n            console.warn('No packageOid available for discount lookup');\n        }\n\n        // Reservation form: default pax to 1\n        document.getElementById('paxCount').value = '1';\n\n        // Read client-side validation flag from Web.config AppSettings\n        // If AppSettings[\"ClientValidationEnabled\"] == \"true\" then enable passenger field validation\n        const clientValidationEnabled = 'true' === 'true';\n\n        // Passengers table management\n        const passengersBody = document.getElementById('passengersBody');\n        let passengerIndex = 0;\n        function addPassenger(p) {\n            passengerIndex++;\n            // Desktop row\n            const tr = document.createElement('tr');\n            tr.dataset.idx = passengerIndex;\n            tr.innerHTML = `\n                <td class=\"align-middle\">${passengerIndex}</td>\n                <td>\n                    <input class=\"form-control form-control-sm\" name=\"passportNo\" value=\"${p?.passportNo || ''}\" />\n                </td>\n                <td>\n                    <input type=\"date\" class=\"form-control form-control-sm\" name=\"issueDate\" value=\"${p?.issueDate || ''}\" />\n                </td>\n                <td>\n                    <input type=\"date\" class=\"form-control form-control-sm\" name=\"expiryDate\" value=\"${p?.expiryDate || ''}\" />\n                </td>\n                <td>\n                    <input class=\"form-control form-control-sm\" name=\"surname\" value=\"${p?.surname || ''}\" />\n                </td>\n                <td>\n                    <input class=\"form-control form-control-sm\" name=\"givenName\" value=\"${p?.givenName || ''}\" />\n                </td>\n                <td>\n                    <select class=\"form-select form-select-sm\" name=\"gender\">\n                        <option value=\"\">--</option>\n                        <option value=\"Male\" ${p?.gender === 'Male' ? 'selected' : ''}>Male</option>\n                        <option value=\"Female\" ${p?.gender === 'Female' ? 'selected' : ''}>Female</option>\n                        <option value=\"Other\" ${p?.gender === 'Other' ? 'selected' : ''}>Other</option>\n                    </select>\n                </td>\n                <td>\n                    <input type=\"date\" class=\"form-control form-control-sm\" name=\"dob\" value=\"${p?.dob || ''}\" />\n                </td>\n                <td class=\"text-center align-middle\">\n                    <div class=\"form-check d-flex justify-content-center align-items-center\" style=\"height:100%;\">\n                        <input class=\"form-check-input m-0\" type=\"checkbox\" name=\"childWithoutBed\" ${p?.childWithoutBed || p?.ChildWithoutBed ? 'checked' : ''} />\n                    </div>\n                </td>\n                <td class=\"text-center align-middle\">\n                    <div class=\"form-check d-flex justify-content-center align-items-center\" style=\"height:100%;\">\n                        <input class=\"form-check-input m-0\" type=\"checkbox\" name=\"additionalBaggage\" ${p?.additionalBaggage || p?.AdditionalBaggage ? 'checked' : ''} />\n                    </div>\n                </td>\n            `;\n            passengersBody.appendChild(tr);\n\n            // Mobile card\n            const cardsContainer = document.getElementById('passengersCards');\n            const cardCol = document.createElement('div');\n            cardCol.className = 'col-12';\n            cardCol.dataset.idx = passengerIndex;\n            cardCol.innerHTML = `\n                <div class=\"card\">\n                    <div class=\"card-header passenger-card-header\">\n                        <strong>Passenger ${passengerIndex}</strong>\n                    </div>\n                    <div class=\"card-body\">\n                        <div class=\"row g-2\">\n                            <div class=\"col-12 col-sm-6\">\n                                <label class=\"form-label small\">Passport No</label>\n                                <input class=\"form-control form-control-sm\" name=\"passportNo\" value=\"${p?.passportNo || ''}\" />\n                            </div>\n                            <div class=\"col-6 col-sm-3\">\n                                <label class=\"form-label small\">Issue</label>\n                                <input type=\"date\" class=\"form-control form-control-sm\" name=\"issueDate\" value=\"${p?.issueDate || ''}\" />\n                            </div>\n                            <div class=\"col-6 col-sm-3\">\n                                <label class=\"form-label small\">Expiry</label>\n                                <input type=\"date\" class=\"form-control form-control-sm\" name=\"expiryDate\" value=\"${p?.expiryDate || ''}\" />\n                            </div>\n                            <div class=\"col-12 col-sm-6\">\n                                <label class=\"form-label small\">Surname</label>\n                                <input class=\"form-control form-control-sm\" name=\"surname\" value=\"${p?.surname || ''}\" />\n                            </div>\n                            <div class=\"col-12 col-sm-6\">\n                                <label class=\"form-label small\">Given Name</label>\n                                <input class=\"form-control form-control-sm\" name=\"givenName\" value=\"${p?.givenName || ''}\" />\n                            </div>\n                            <div class=\"col-12 col-sm-4\">\n                                <label class=\"form-label small\">Gender</label>\n                                <select class=\"form-select form-select-sm\" name=\"gender\">\n                                    <option value=\"\">--</option>\n                                    <option value=\"Male\" ${p?.gender === 'Male' ? 'selected' : ''}>Male</option>\n                                    <option value=\"Female\" ${p?.gender === 'Female' ? 'selected' : ''}>Female</option>\n                                    <option value=\"Other\" ${p?.gender === 'Other' ? 'selected' : ''}>Other</option>\n                                </select>\n                            </div>\n                            <div class=\"col-6 col-sm-4\">\n                                <label class=\"form-label small\">DOB</label>\n                                <input type=\"date\" class=\"form-control form-control-sm\" name=\"dob\" value=\"${p?.dob || ''}\" />\n                            </div>\n                            <div class=\"col-6 col-sm-4\">\n                                <label class=\"form-label small\">Child Without Bed</label>\n                                <div class=\"form-check\">\n                                    <input class=\"form-check-input\" type=\"checkbox\" name=\"childWithoutBed\" ${p?.childWithoutBed || p?.ChildWithoutBed ? 'checked' : ''} />\n                                </div>\n                            </div>\n                            <div class=\"col-12 col-sm-4\">\n                                <label class=\"form-label small\">Additional Baggage</label>\n                                <div class=\"form-check\">\n                                    <input class=\"form-check-input\" type=\"checkbox\" name=\"additionalBaggage\" ${p?.additionalBaggage || p?.AdditionalBaggage ? 'checked' : ''} />\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            `;\n            cardsContainer.appendChild(cardCol);\n\n            // Add event listener to set expiry date automatically when issue date is selected (both row and card)\n            const issueDateInputs = [tr.querySelector('input[name=\"issueDate\"]'), cardCol.querySelector('input[name=\"issueDate\"]')].filter(Boolean);\n            const expiryDateInputs = [tr.querySelector('input[name=\"expiryDate\"]'), cardCol.querySelector('input[name=\"expiryDate\"]')].filter(Boolean);\n\n            issueDateInputs.forEach((issueEl, idx) => {\n                const expiryEl = expiryDateInputs[idx] || expiryDateInputs[0];\n                if (!issueEl || !expiryEl) return;\n                issueEl.addEventListener('change', function() {\n                    if (this.value) {\n                        const issueDate = new Date(this.value);\n                        const expiryDate = new Date(issueDate);\n                        expiryDate.setFullYear(expiryDate.getFullYear() + 5);\n                        const year = expiryDate.getFullYear();\n                        const month = String(expiryDate.getMonth() + 1).padStart(2, '0');\n                        const day = String(expiryDate.getDate()).padStart(2, '0');\n                        expiryEl.value = `${year}-${month}-${day}`;\n                        // Keep other expiry in sync\n                        expiryDateInputs.forEach(e => { if (e !== expiryEl) e.value = expiryEl.value; });\n                    }\n                });\n            });\n        }\n\n        function syncPassengersWithPAX() {\n            const paxCount = parseInt(document.getElementById('paxCount').value) || 0;\n            const currentRowCount = passengersBody.querySelectorAll('tr').length;\n            const cardsContainer = document.getElementById('passengersCards');\n            const currentCardCount = cardsContainer ? cardsContainer.querySelectorAll('[data-idx]').length : 0;\n\n            if (paxCount > currentRowCount) {\n                // Add more rows\n                for (let i = currentRowCount; i < paxCount; i++) {\n                    addPassenger();\n                }\n            } else if (paxCount < currentRowCount) {\n                // Remove excess rows\n                const rows = Array.from(passengersBody.querySelectorAll('tr'));\n                for (let i = currentRowCount - 1; i >= paxCount; i--) {\n                    if (rows[i]) rows[i].remove();\n                }\n                // Remove corresponding cards on mobile as well\n                if (cardsContainer) {\n                    const cardCols = Array.from(cardsContainer.querySelectorAll('[data-idx]'));\n                    for (let i = cardCols.length - 1; i >= paxCount; i--) {\n                        if (cardCols[i]) cardCols[i].remove();\n                    }\n                }\n                rebuildPassengerNumbers();\n            }\n        }\n\n        // Listen to PAX changes\n        document.getElementById('paxCount').addEventListener('change', function (e) {\n            // If option is disabled (exceeds seats), show message and revert\n            const opt = e.target.selectedOptions && e.target.selectedOptions[0];\n            if (opt && opt.disabled) {\n                setMessage('Cannot select more PAX than available seats.', 'warning');\n                // revert to nearest valid value\n                const avail = getAvailableSeatsNumber();\n                e.target.value = avail > 0 ? String(avail) : '';\n            }\n            syncPassengersWithPAX();\n        });\n\n        // Initialize passengers based on default PAX\n        syncPassengersWithPAX();\n        // Apply pax option limits based on available seats initially\n        applyPaxLimit(false);\n\n        function rebuildPassengerNumbers() {\n            passengerIndex = 0;\n            Array.from(passengersBody.querySelectorAll('tr')).forEach(tr => { passengerIndex++; tr.children[0].textContent = passengerIndex; tr.dataset.idx = passengerIndex; });\n            // Update card indexes\n            const cardsContainer = document.getElementById('passengersCards');\n            if (cardsContainer) {\n                let idx = 0;\n                Array.from(cardsContainer.querySelectorAll('[data-idx]')).forEach(cardCol => {\n                    idx++;\n                    cardCol.dataset.idx = idx;\n                    const header = cardCol.querySelector('.passenger-card-header');\n                    if (header) header.innerHTML = `<strong>Passenger ${idx}</strong>`;\n                });\n            }\n        }\n\n        // Register button behavior: simple client-side validation then show data\n        function clearValidation() {\n            // remove invalid classes\n            document.querySelectorAll('.is-invalid').forEach(el => el.classList.remove('is-invalid'));\n            // remove passenger-generated feedback messages\n            document.querySelectorAll('.pax-invalid-feedback').forEach(el => el.remove());\n        }\n\n        function validateReservation() {\n            // Notes is optional, do not include it in required fields\n            const fields = ['customerSelect', 'familyHead', 'roomType', 'paxCount'];\n            for (const id of fields) {\n                const el = document.getElementById(id);\n                if (!el) continue;\n                // Skip validation for disabled customer dropdown (customer users)\n                if (id === 'customerSelect') {\n                    // Ensure a customer was selected from suggestions (hidden field populated)\n                    const hid = document.getElementById('customerOidHidden');\n                    if (el.disabled) continue;\n                    if (!hid || !hid.value || hid.value.trim() === '') {\n                        el.classList.add('is-invalid');\n                        el.focus();\n                        return false;\n                    }\n                    continue;\n                }\n                if (!el.checkValidity()) {\n                    el.classList.add('is-invalid');\n                    el.focus();\n                    return false;\n                }\n            }\n            return true;\n        }\n\n        function validatePassengers() {\n            const rows = Array.from(passengersBody.querySelectorAll('tr'));\n            if (rows.length === 0) {\n                setMessage('At least one passenger is required.', 'warning');\n                return false;\n            }\n\n            if (!clientValidationEnabled) return true; // client validation disabled, accept current optional behavior\n\n            // When client validation is enabled, ensure all passenger fields are filled\n            for (const r of rows) {\n                const required = [\n                    {name: 'passportNo', label: 'Passport No'},\n                    {name: 'issueDate', label: 'Issue Date'},\n                    {name: 'expiryDate', label: 'Expiry Date'},\n                    {name: 'surname', label: 'Surname'},\n                    {name: 'givenName', label: 'Given Name'},\n                    {name: 'dob', label: 'DOB'},\n                    {name: 'gender', label: 'Gender'}\n                ];\n\n                for (const f of required) {\n                    const el = r.querySelector('[name=\"' + f.name + '\"]');\n                    if (!el) {\n                        setMessage(`Missing field ${f.label} in passenger row.`, 'warning');\n                        return false;\n                    }\n                    // check checkbox separately\n                    if (el.type === 'checkbox') {\n                        // checkbox may be optional; treat presence as ok\n                        continue;\n                    }\n                    if (!el.value || String(el.value).trim() === '') {\n                        el.classList.add('is-invalid');\n                        setMessage(`Please fill ${f.label} for all passengers.`, 'warning');\n                        return false;\n                    }\n                }\n            }\n\n            return true;\n        }\n\n        // Remove invalid class on input/change and keep card/table inputs synchronized\n        function syncPassengerField(target) {\n            try {\n                if (!target || !target.name) return;\n                // find parent passenger index (tr or card column)\n                const tr = target.closest('tr[data-idx]');\n                const cardCol = target.closest('#passengersCards [data-idx], [data-idx].card, [data-idx]');\n                const idx = (tr && tr.dataset && tr.dataset.idx) || (cardCol && cardCol.dataset && cardCol.dataset.idx);\n                if (!idx) return;\n\n                // Determine counterpart container\n                const cardsContainer = document.getElementById('passengersCards');\n                const counterpartCard = cardsContainer ? cardsContainer.querySelector(`[data-idx=\"${idx}\"]`) : null;\n                const counterpartRow = document.getElementById('passengersBody') ? document.getElementById('passengersBody').querySelector(`tr[data-idx=\"${idx}\"]`) : null;\n\n                // If changed in row, update card; if changed in card, update row\n                if (tr && counterpartCard) {\n                    const pair = counterpartCard.querySelector(`[name=\"${target.name}\"]`);\n                    if (!pair) return;\n                    if (target.type === 'checkbox') pair.checked = target.checked;\n                    else pair.value = target.value;\n                } else if (cardCol && counterpartRow) {\n                    const pair = counterpartRow.querySelector(`[name=\"${target.name}\"]`);\n                    if (!pair) return;\n                    if (target.type === 'checkbox') pair.checked = target.checked;\n                    else pair.value = target.value;\n                }\n            } catch (ex) {\n                console.error('syncPassengerField error', ex);\n            }\n        }\n\n        document.addEventListener('input', function (e) {\n            if (e.target && e.target.classList && e.target.classList.contains('is-invalid')) e.target.classList.remove('is-invalid');\n            syncPassengerField(e.target);\n        });\n        document.addEventListener('change', function (e) {\n            if (e.target && e.target.classList && e.target.classList.contains('is-invalid')) e.target.classList.remove('is-invalid');\n            syncPassengerField(e.target);\n        });\n\n        document.getElementById('registerBtn').addEventListener('click', async function (e) {\n\n            e.preventDefault();\n            clearValidation();\n            // Disable the register button to prevent duplicate submissions until response is received\n            try {\n                this.disabled = true;\n            } catch (ignore) {}\n            const accept = document.getElementById('acceptTerms').checked;\n            if (!accept) { setMessage('You must accept the Terms & Conditions before registering.', 'warning'); try { this.disabled = false; } catch(e){} return; }\n\n            if (!validateReservation()) { try { this.disabled = false; } catch(e){} return; }\n            if (!validatePassengers()) { try { this.disabled = false; } catch(e){} return; }\n\n            // gather reservation and passengers\n            // Prefer the hidden field (selected Oid). Fallback to visible input value if hidden missing.\n            const customerOid = (document.getElementById('customerOidHidden').value || document.getElementById('customerSelect').value || '').trim();\n\n            const reservation = {\n                customer: customerOid,\n                familyHead: document.getElementById('familyHead').value,\n                roomType: document.getElementById('roomType').value,\n                pax: document.getElementById('paxCount').value,\n                //notes: document.getElementById('notes').value + \"||\" + document.getElementById('customerSelect').value,\n                notes: document.getElementById('notes').value,\n                groupOid: oid\n            };\n\n            const paxRows = Array.from(passengersBody.querySelectorAll('tr'));\n                const passengers = paxRows.map(r => ({\n                passportNo: r.querySelector('[name=\"passportNo\"]').value,\n                issueDate: r.querySelector('[name=\"issueDate\"]').value,\n                expiryDate: r.querySelector('[name=\"expiryDate\"]').value,\n                surname: r.querySelector('[name=\"surname\"]').value,\n                givenName: r.querySelector('[name=\"givenName\"]').value,\n                dob: r.querySelector('[name=\"dob\"]').value,\n                gender: r.querySelector('[name=\"gender\"]').value,\n                childWithoutBed: !!r.querySelector('[name=\"childWithoutBed\"]') && r.querySelector('[name=\"childWithoutBed\"]').checked,\n                additionalBaggage: !!r.querySelector('[name=\"additionalBaggage\"]') && r.querySelector('[name=\"additionalBaggage\"]').checked\n            }));\n\n            // Determine if this is a remote or local group\n            const isRemoteGroup = item.EndPoint && item.EndPoint.trim() !== '';\n\n            // Determine the per-person price based on the selected room type and compute the total amount\n            function getSelectedRoomPrice() {\n                const roomTypeSelect = document.getElementById('roomType');\n                const selectedText =\n                    roomTypeSelect?.selectedOptions?.[0]?.textContent?.trim().toLowerCase() || '';\n\n                let price = null;\n\n                if (selectedText.includes('sharing')) {\n                    price = item.Sharing ?? item.sharing;\n                }\n                else if (selectedText.includes('quad')) {\n                    price = item.QuadRoom ?? item.quadRoom ?? item.Quad ?? item.quad;\n                }\n                else if (selectedText.includes('triple')) {\n                    price = item.TripleRoom ?? item.tripleRoom ?? item.Triple ?? item.triple;\n                }\n                else if (selectedText.includes('double')) {\n                    price = item.DoubleRoom ?? item.doubleRoom ?? item.Double ?? item.double;\n                }\n\n                const num = Number(price);\n                return isNaN(num) ? 0 : num;\n            }\n\n            const margin = Number(item.Margin ?? item.margin) || 0;\n            const paxCount = parseInt(reservation.pax) || 1;\n            const roomPrice = getSelectedRoomPrice();\n            const totalAmount = roomPrice;\n\n            // Build DTO similar to UmrahGroupRegister.razor and post to server OData controller\n            const dto = {\n                GroupOid: item.GroupOid || item.groupOid || item.PackageOid || item.packageOid || item.Oid || oid,\n                ReservationNo: '',\n                ReservationDate: new Date().toISOString(),\n                FamilyHead: reservation.familyHead,\n                Notes: reservation.notes,\n                PAX: parseInt(reservation.pax) || 1,\n                RoomQty: null,\n                TotalAmount: totalAmount,\n                Margin: margin,\n                PackageDiscount: isRemoteGroup ? totalDiscountAmount : 0, // Only save discount for remote groups\n                EndPoint: item.EndPoint || null,\n                DomainToken: item.DomainToken || null,\n                UserId: item.CustomerOid || item.customerOid || null,\n                PackageOid: item.PackageOid || item.packageOid || item.Oid || oid,\n                PackageTitle: item.PackageCode || item.packageCode || item.GroupTitle || item.groupTitle || '',\n                CustomerOid: (reservation.customer && reservation.customer.length > 0) ? reservation.customer : null,\n                Mutamers: passengers.map(p => ({\n                    ReservationOid: null, // server will attach\n                    PassportNo: p.passportNo || '',\n                    FamilyName: p.surname || '',\n                    FirstName: p.givenName || '',\n                    PNR: '',\n                    TicketNo: '',\n                    Gender: p.gender || '',\n                    ChildWithoutBed: p.childWithoutBed ? true : false,\n                    AdditionalBaggage: p.additionalBaggage ? true : false,\n                    DOB: p.dob ? new Date(p.dob).toISOString() : null,\n                    IssueDate: p.issueDate ? new Date(p.issueDate).toISOString() : null,\n                    ExpiryDate: p.expiryDate ? new Date(p.expiryDate).toISOString() : null,\n                    ContactNo: ''\n                }))\n            };\n\n            // Room type resolution removed - select options contain Oid as value\n\n            // Determine POST URL for UmrReservation\n            // 1. If item.EndPoint is empty or null, use local XPO collection (via /UMR/SaveReservation)\n            // 2. If item.EndPoint has address, use this address as base for /api/odata/UmrReservation\n            let postUrl = null;\n            let useLocalEndpoint = !item.EndPoint || item.EndPoint.trim() === '';\n\n            if (useLocalEndpoint) {\n                // Use local XPO-based controller endpoint\n                postUrl = window.location.origin + '/UMR/SaveReservation';\n            } else {\n                // Use external OData endpoint\n                try {\n                    const storedBase = sessionStorage.getItem('selectedUmrGroup_baseUrl_' + oid) || sessionStorage.getItem('selectedUmrGroup_baseUrl');\n                    if (storedBase && storedBase.trim() !== '') {\n                        // Ensure storedBase is a valid URL with protocol and domain\n                        if (storedBase.startsWith('http://') || storedBase.startsWith('https://')) {\n                            postUrl = storedBase.replace(/\\/$/, '') + '/api/UmrReservation';\n                        } else {\n                            console.warn('Invalid storedBase URL (missing protocol):', storedBase);\n                        }\n                    }\n                } catch (ex) { console.warn('Failed to read stored baseUrl', ex); }\n                if (!postUrl && item.EndPoint) {\n                    const idx2 = item.EndPoint.indexOf('/api');\n                    if (idx2 !== -1) {\n                        const base2 = item.EndPoint.substring(0, idx2);\n                        // Validate base2 is a complete URL\n                        if (base2.startsWith('http://') || base2.startsWith('https://')) {\n                            postUrl = base2 + '/api/UmrReservation';\n                        } else {\n                            console.warn('Invalid EndPoint base URL (missing protocol):', base2);\n                        }\n                    } else {\n                        // Validate endpoint is a complete URL\n                        if (item.EndPoint.startsWith('http://') || item.EndPoint.startsWith('https://')) {\n                            postUrl = item.EndPoint.replace(/\\/$/, '') + '/api/UmrReservation';\n                        } else {\n                            console.warn('Invalid EndPoint URL (missing protocol):', item.EndPoint);\n                        }\n                    }\n                }\n                // Fallback to current origin if no valid external URL was found\n                if (!postUrl) {\n                    console.warn('No valid external endpoint found, using current origin as fallback');\n                    postUrl = window.location.origin + '/api/UmrReservation';\n                }\n            }\n\n            try {\n                // Attach selected RoomType Oid (options hold Oid as value) and name\n                const selEl = document.getElementById('roomType');\n                if (selEl && selEl.value) {\n                    dto.RoomTypeOid = selEl.value;\n                    dto.RoomTypeName = (selEl.selectedOptions && selEl.selectedOptions[0]) ? selEl.selectedOptions[0].textContent : null;\n                }\n            } catch (ex) { console.warn('Failed to attach selected RoomTypeOid', ex); }\n\n            try {\n                if (useLocalEndpoint) {\n                    // For local XPO endpoint, post directly without external suffix or domain token logic\n                    setMessage('Submitting reservation to local database...', 'info');\n                    // Ensure Supplier is set when saving locally (use DTO or group info if available)\n                    try {\n                        const supplierVal = item?.Supplier || item?.SupplierOid || item?.supplier || item?.supplierOid || item?.SupplierId || null;\n                        if (supplierVal) dto.Supplier = String(supplierVal);\n                    } catch (sEx) { /* ignore */ }\n\n                    const resp = await fetch(postUrl, {\n                        method: 'POST',\n                        headers: { 'Content-Type': 'application/json' },\n                        body: JSON.stringify(dto)\n                    });\n\n                    const text = await resp.text();\n                    let parsed = null;\n                    try { parsed = JSON.parse(text); } catch { parsed = text; }\n\n                    if (resp.status === 200 || resp.ok) {\n                        // Success\n                        const result = parsed;\n                        console.log('Reservation saved locally', result);\n                        const resNo = result.ReservationNo || result.reservationNo || (result.value && result.value.ReservationNo) || (result.value && result.value.reservationNo) || null;\n                        // Show success UI and pass reservation object\n                        showReservationSuccessUI(result, resNo);\n                    }\n                    else {\n                        console.error('Failed to create reservation', resp.status, parsed);\n                        let errMsg = 'Failed to create reservation.';\n                        if (parsed && parsed.error) errMsg = parsed.error;\n                        else if (parsed && parsed.errors) errMsg = JSON.stringify(parsed.errors);\n                        else if (typeof parsed === 'string') errMsg = parsed;\n                        setMessage(errMsg, 'danger');\n                    }\n                } else {\n                    // For external endpoint, use domain-specific routing with /external suffix\n                    try {\n                        // Preserve the user-selected customer (from the dropdown) so we can\n                        // ensure local saves use the selected CustomerOid even when the\n                        // reservation was created on a remote endpoint which may require\n                        // a domain token instead.\n                        const selectedCustomerOid = dto.CustomerOid;\n\n                        const storedBase = sessionStorage.getItem('selectedUmrGroup_baseUrl_' + oid) || sessionStorage.getItem('selectedUmrGroup_baseUrl');\n                        const storedDomain = sessionStorage.getItem('selectedUmrGroup_domainToken_' + oid) || sessionStorage.getItem('selectedUmrGroup_domainToken');\n\n                        // If a stored domain token exists use it for DomainToken (and for\n                        // remote CustomerOid if required by the external API). Do not\n                        // overwrite selectedCustomerOid variable - we'll restore it before\n                        // saving locally.\n                        if (storedDomain) {\n                            dto.DomainToken = storedDomain;\n                            // Use storedDomain as the CustomerOid for the remote POST if needed\n                            dto.CustomerOid = storedDomain;\n                        } else if (item.CustomerOid) {\n                            // Fallback to group-provided customer if present for remote POST\n                            dto.CustomerOid = item.CustomerOid;\n                        } else {\n                            // Otherwise keep whatever was selected by the user\n                            dto.CustomerOid = selectedCustomerOid || null;\n                        }\n\n                        // Attach the selectedCustomerOid to dto._selectedCustomer for later\n                        // restoration before saving locally\n                        dto._selectedCustomer = selectedCustomerOid || null;\n                    } catch (ex) { console.warn('Failed to attach domain/base info to DTO', ex); }\n\n                    var postUrlExternal = postUrl + \"/external\";\n                    if (dto.DomainToken != null && dto.DomainToken.length > 0) {\n                        postUrl = postUrlExternal;\n                    }\n\n                    setMessage('Submitting reservation to remote endpoint...', 'info');\n                    const resp = await fetch(postUrl, {\n                        method: 'POST',\n                        headers: { 'Content-Type': 'application/json' },\n                        body: JSON.stringify(dto)\n                    });\n\n                    const text = await resp.text();\n                    let parsed = null;\n                    try { parsed = JSON.parse(text); } catch { parsed = text; }\n\n                    if (resp.status === 201 || resp.ok) {\n                        // Created\n                        const created = parsed;\n                        console.log('Reservation created on remote endpoint', created);\n                        const resNo = (created && created.ReservationNo) ? created.ReservationNo : (created && created.value && created.value.ReservationNo ? created.value.ReservationNo : null);\n\n                        // Also save to local database\n                        try {\n                            setMessage(resNo ? `Reservation created remotely: ${resNo}. Saving locally...` : 'Reservation created remotely. Saving locally...', 'info');\n\n                            // Update DTO with reservation number from remote\n                            if (resNo) {\n                                dto.ReservationNo = resNo;\n                                // Also store the external provider's reservation number\n                                // so local records can reference the upstream identifier.\n                                dto.ServiceProviderReservationNo = resNo;\n                            }\n\n                            const localPostUrl = window.location.origin + '/UMR/SaveReservation';\n                            // Ensure local save uses the customer selected in the dropdown.\n                            try {\n                                if (dto && dto._selectedCustomer) {\n                                    dto.CustomerOid = dto._selectedCustomer;\n                                    delete dto._selectedCustomer;\n                                }\n                            } catch (e) { /* ignore */ }\n                            // Ensure Supplier is set when saving locally after remote creation\n                            try {\n                                const supplierVal = item?.Supplier || item?.SupplierOid || item?.supplier || item?.supplierOid || item?.SupplierId || null;\n                                if (supplierVal) dto.Supplier = String(supplierVal);\n                            } catch (sEx) { /* ignore */ }\n                            const localResp = await fetch(localPostUrl, {\n                                method: 'POST',\n                                headers: { 'Content-Type': 'application/json' },\n                                body: JSON.stringify(dto)\n                            });\n\n                            const localText = await localResp.text();\n                            let localParsed = null;\n                            try { localParsed = JSON.parse(localText); } catch { localParsed = localText; }\n\n                        if (localResp.status === 200 || localResp.ok) {\n                                console.log('Reservation also saved locally', localParsed);\n                                // Show success UI and pass remote created object (it may contain ReservationNo) and localParsed as backup\n                                showReservationSuccessUI(localParsed || created, resNo);\n                            } else {\n                                console.warn('Failed to save reservation locally', localResp.status, localParsed);\n                                // Still show success UI but notify user local save failed\n                                showReservationSuccessUI(created, resNo);\n                            }\n                        } catch (localEx) {\n                            console.error('Error saving reservation locally', localEx);\n                            setMessage(resNo ? `Reservation created: ${resNo} (saved remotely only)` : 'Reservation created successfully (saved remotely only).', 'warning');\n                        }\n\n                        // Success UI already shown after local save (or shown with remote info when local save failed).\n                        // Do not call showReservationSuccessUI(created, resNo) here to avoid overriding\n                        // the local reservation number displayed by the earlier call.\n                    }\n                    else {\n                        console.error('Failed to create reservation', resp.status, parsed);\n                        let errMsg = 'Failed to create reservation.';\n                        if (parsed && parsed.error) errMsg = parsed.error;\n                        else if (parsed && parsed.errors) errMsg = JSON.stringify(parsed.errors);\n                        else if (typeof parsed === 'string') errMsg = parsed;\n                        setMessage(errMsg, 'danger');\n                    }\n                }\n            }\n            catch (ex) {\n                console.error('Error posting reservation', ex);\n                setMessage('Error submitting reservation. See console for details.', 'danger');\n            }\n            finally {\n                // Re-enable the register button when processing is complete (unless UI replaced by success view)\n                try { document.getElementById('registerBtn').disabled = false; } catch (err) { }\n            }\n        });\n\n        // NOTE: duplicate/partial autocomplete wiring removed. The dedicated autocomplete IIFE\n        // further down is the authoritative implementation and has been enhanced to\n        // ensure the toggle button always opens the list (even when input contains text)\n        // and to highlight the currently selected value in the suggestions list.\n        // Initialize customer input: preselect if current user is a customer or group provided a customer\n        (function () {\n            const input = document.getElementById('customerSelect');\n            const hidden = document.getElementById('customerOidHidden');\n            if (!input || !hidden) return;\n            try {\n                if (currentUser.isCustomer && currentUser.oid) {\n                    input.value = currentUser.fullName || '';\n                    hidden.value = currentUser.oid;\n                    input.disabled = true;\n                    input.setAttribute('readonly', 'readonly');\n                    input.style.backgroundColor = '#e9ecef';\n                    input.style.cursor = 'not-allowed';\n                    console.log('Auto-selected customer:', currentUser.fullName, '(', currentUser.oid, ')');\n                } else {\n                    const sel = item.CustomerOid || item.CustomerId || item.customerOid;\n                    if (sel) {\n                        hidden.value = sel;\n                        input.value = item.CustomerName || item.CustomerFullName || item.FullName || '';\n                    }\n                }\n            } catch (ex) {\n                console.warn('Customer init failed', ex);\n            }\n        })();\n\n        // Populate Room Type dropdown using XPO collection via controller\n        async function populateRoomTypes() {\n            const select = document.getElementById('roomType');\n            if (!select) return;\n            select.innerHTML = '<option value=\"\">-- Select --</option>';\n\n            try {\n                // Use local controller endpoint that reads from XPO collection\n                const apiUrl = '/UMR/GetRoomTypes';\n                console.log('[RoomTypes] Loading from', apiUrl);\n\n                const r = await fetch(apiUrl);\n\n                if (!r.ok) {\n                    const txt = await r.text();\n                    console.error('[RoomTypes] Failed to load', r.status, txt);\n                    setMessage('Failed to load room types. See console for details.', 'warning');\n                    return;\n                }\n\n                const roomTypes = await r.json();\n\n                if (!Array.isArray(roomTypes)) {\n                    console.error('[RoomTypes] Unexpected response', roomTypes);\n                    setMessage('Unexpected room types response format.', 'warning');\n                    return;\n                }\n\n                for (const rt of roomTypes) {\n                    const opt = document.createElement('option');\n                    opt.value = rt.Oid || rt.oid || '';\n                    opt.textContent = rt.Title || rt.title || opt.value;\n                    select.appendChild(opt);\n                }\n\n                console.log('[RoomTypes] Available options:', Array.from(select.options).map(o => ({ value: o.value, text: o.textContent })));\n\n                // First, try to preselect room type from UmrahGroups page (stored in sessionStorage)\n                const storedRoomType = sessionStorage.getItem('selectedUmrGroup_roomType_' + oid);\n                console.log('[RoomTypes] Stored room type from sessionStorage:', storedRoomType);\n\n                if (storedRoomType) {\n                    // Try case-insensitive match for GUIDs\n                    const storedLower = storedRoomType.toLowerCase();\n                    let matchFound = false;\n\n                    for (const opt of Array.from(select.options)) {\n                        if (opt.value.toLowerCase() === storedLower) {\n                            select.value = opt.value;\n                            matchFound = true;\n                            console.log('[RoomTypes] Successfully preselected room type from UmrahGroups (case-insensitive match)');\n                            break;\n                        }\n                    }\n\n                    if (!matchFound) {\n                        // Try direct match\n                        select.value = storedRoomType;\n                        if (select.value === storedRoomType) {\n                            console.log('[RoomTypes] Successfully preselected room type from UmrahGroups (direct match)');\n                        } else {\n                            console.warn('[RoomTypes] Failed to preselect - stored value not found in dropdown options');\n                            console.warn('[RoomTypes] Stored value:', storedRoomType);\n                            console.warn('[RoomTypes] Available values:', Array.from(select.options).map(o => o.value));\n                        }\n                    }\n                }\n                // If no stored room type, then check if DTO provided one\n                else {\n                    console.log('[RoomTypes] No stored room type found, checking DTO properties');\n                    // Set selected if DTO provided (prefer Oid)\n                    const selOid = item.RoomTypeOid || item.roomTypeOid || item.RoomTypeOid;\n                    if (selOid) {\n                        select.value = selOid;\n                        console.log('[RoomTypes] Set room type from DTO Oid:', selOid);\n                    } else {\n                        const selTitle = item.RoomTypeName || item.RoomType || item.roomTypeName;\n                        if (selTitle) {\n                            // Try to find option by text\n                            for (const opt of Array.from(select.options)) {\n                                if ((opt.textContent || '').trim() === selTitle.trim()) {\n                                    select.value = opt.value;\n                                    console.log('[RoomTypes] Set room type from DTO name:', selTitle, '-> Oid:', opt.value);\n                                    break;\n                                }\n                            }\n                        }\n                    }\n                }\n\n                console.log('[RoomTypes] Successfully loaded', roomTypes.length, 'room types');\n            }\n            catch (ex) {\n                console.error('[RoomTypes] Error loading room types', ex);\n                setMessage('Error loading room types. See console for details.', 'warning');\n            }\n        }\n\n        populateRoomTypes();\n\n    })();\n    // Customer autocomplete logic\n    (function(){\n        const input = document.getElementById('customerSelect');\n        const suggestions = document.getElementById('customerSuggestions');\n        const hidden = document.getElementById('customerOidHidden');\n        let currentIdx = -1;\n        let lastQuery = '';\n        if (!input) return;\n\n        function clearSuggestions(){ suggestions.innerHTML=''; suggestions.style.display='none'; currentIdx=-1; }\n\n        function renderList(items){\n            suggestions.innerHTML = '';\n            if (!items || items.length === 0){ clearSuggestions(); return; }\n            // determine selected oid to highlight it\n            const selOid = (hidden && hidden.value) ? hidden.value : '';\n            currentIdx = -1;\n            items.forEach((it, i) => {\n                const el = document.createElement('button');\n                el.type = 'button';\n                el.className = 'list-group-item list-group-item-action';\n                el.textContent = it.Text || it.text || it.FullName || it.name || '';\n                el.dataset.oid = it.Id || it.id || it.Value || it.value || it.Oid || '';\n                el.addEventListener('click', function(){ selectItem(el); });\n                suggestions.appendChild(el);\n                // highlight if matches selected oid or exact text match\n                if (selOid && (el.dataset.oid === selOid)) {\n                    el.classList.add('active');\n                    currentIdx = i;\n                    // ensure input shows the selected text\n                    input.value = el.textContent;\n                    hidden.value = selOid;\n                } else if (!selOid && input.value && el.textContent === input.value) {\n                    el.classList.add('active');\n                    currentIdx = i;\n                }\n            });\n            suggestions.style.display = 'block';\n            // if there is a selected item, scroll it into view\n            if (currentIdx >= 0) {\n                const itemsEl = suggestions.querySelectorAll('.list-group-item');\n                if (itemsEl[currentIdx]) itemsEl[currentIdx].scrollIntoView({ block: 'nearest' });\n            }\n        }\n\n        function selectItem(el){\n            if (!el) return;\n            input.value = el.textContent;\n            hidden.value = el.dataset.oid || '';\n            clearSuggestions();\n        }\n\n        let debounceTimer = null;\n\n        // Helper to fetch and render suggestions for a given query (empty = default shortlist)\n        function fetchAndRender(q, immediate) {\n            // do not clear hidden when explicitly requesting the list (toggle behavior)\n            if (!immediate) {\n                hidden.value = ''; // clear selection when typing normally\n            }\n\n            const url = q ? '/Customers/SearchCustomers?query=' + encodeURIComponent(q) : '/Customers/SearchCustomers';\n            fetch(url, { headers: { 'Accept': 'application/json' } })\n                .then(r => r.json())\n                .then(data => { renderList(data || []); })\n                .catch(err => { console.error('Customer search failed', err); clearSuggestions(); });\n        }\n\n        input.addEventListener('input', function(e){\n            const q = input.value.trim();\n            if (debounceTimer) clearTimeout(debounceTimer);\n            if (!q){\n                // show default shortlist quickly\n                fetchAndRender('', false);\n                return;\n            }\n            debounceTimer = setTimeout(function(){\n                if (q === lastQuery) return;\n                lastQuery = q;\n                fetchAndRender(q, false);\n            }, 250);\n        });\n\n        // When input is focused or clicked, open suggestions for current text (preserve selection)\n        input.addEventListener('focus', function(){\n            const q = input.value.trim();\n            fetchAndRender(q, true);\n        });\n        input.addEventListener('click', function(){\n            const q = input.value.trim();\n            fetchAndRender(q, true);\n        });\n\n        input.addEventListener('blur', function(){ setTimeout(clearSuggestions, 200); });\n\n        input.addEventListener('keydown', function(e){\n            const items = suggestions.querySelectorAll('.list-group-item');\n            if (e.key === 'ArrowDown'){\n                e.preventDefault(); if (items.length === 0) return; currentIdx = Math.min(items.length-1, currentIdx+1); items.forEach(it=>it.classList.remove('active')); items[currentIdx].classList.add('active'); items[currentIdx].scrollIntoView({block:'nearest'});\n            } else if (e.key === 'ArrowUp'){\n                e.preventDefault(); if (items.length === 0) return; currentIdx = Math.max(0, currentIdx-1); items.forEach(it=>it.classList.remove('active')); items[currentIdx].classList.add('active'); items[currentIdx].scrollIntoView({block:'nearest'});\n            } else if (e.key === 'Enter'){\n                if (items.length > 0 && currentIdx >= 0){ e.preventDefault(); selectItem(items[currentIdx]); }\n            } else if (e.key === 'Escape'){\n                clearSuggestions();\n            }\n        });\n\n        // Toggle button should open the suggestions even when input contains text\n        const toggle = document.getElementById('customerToggleBtn');\n        if (toggle) {\n            toggle.addEventListener('click', function(){\n                // If suggestions already visible, hide\n                if (suggestions.style.display && window.getComputedStyle(suggestions).display !== 'none'){\n                    clearSuggestions();\n                    return;\n                }\n                // Fetch list: if input has text, fetch matching items; otherwise fetch default shortlist\n                const q = input.value.trim();\n                // Pass immediate=true so we don't clear hidden (preserve selection highlight)\n                fetchAndRender(q, true);\n                // focus input so keyboard nav works\n                try { input.focus(); } catch (e) { /* ignore */ }\n            });\n        }\n\n        // When the register button is clicked ensure customer selected or show validation\n        const registerBtn = document.getElementById('registerBtn');\n        if (registerBtn){\n            registerBtn.addEventListener('click', function(e){\n                const required = input.getAttribute('required') !== null;\n                if (required && (!hidden.value || hidden.value.trim() === '')){\n                    e.preventDefault();\n                    input.classList.add('is-invalid');\n                    setMessage('Please select a valid customer from the list.', 'warning');\n                    input.focus();\n                    return false;\n                }\n                // allow form submit to continue (existing save logic expected elsewhere)\n                return true;\n            });\n        }\n    })();";

const EXTERNAL_STYLESHEETS = [
  "https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css",
  "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css",
] as const;

function addStylesheet(href: string): HTMLLinkElement | null {
  const existing = Array.from(
    document.querySelectorAll<HTMLLinkElement>('link[rel="stylesheet"]'),
  ).find((link) => link.href === href);

  if (existing) return null;

  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = href;
  link.dataset.umrahReservationAsset = "true";
  document.head.appendChild(link);

  return link;
}

export default function UmrahReservationPage() {
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    document.title = "Umrah Reservation | Green & Gold Theme";

    const insertedLinks = EXTERNAL_STYLESHEETS
      .map(addStylesheet)
      .filter((link): link is HTMLLinkElement => link !== null);

    const root = rootRef.current;
    if (!root) {
      insertedLinks.forEach((link) => link.remove());
      return;
    }

    /*
     * The source page contains a large self-invoking browser script. Appending
     * it after React has mounted the HTML preserves its original DOM behavior.
     */
    const script = document.createElement("script");
    script.type = "text/javascript";
    script.dataset.umrahReservationScript = "true";
    script.text = PAGE_SCRIPT;
    root.appendChild(script);

    return () => {
      script.remove();
      insertedLinks.forEach((link) => link.remove());
    };
  }, []);

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: PAGE_CSS }} />
      <div
        ref={rootRef}
        suppressHydrationWarning
        dangerouslySetInnerHTML={{ __html: PAGE_HTML }}
      />
    </>
  );
}
